-- ============================================================================
-- VERIFICATION QUERY
-- ============================================================================
-- Run this query after migration to verify all categories and counts

SELECT 
    category,
    COUNT(*) as question_count,
    COUNT(CASE WHEN active = true THEN 1 END) as active_count
FROM trivia_items
GROUP BY category
ORDER BY category;

